package net.civeira.phylax.features.access.tenantloginprovider.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class OidcDiscoveryUrlVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property oidc discovery url of tenant login provider ")
  void test_oidc_discovery_url_v_o_builder() {
    Assertions.assertFalse(OidcDiscoveryUrlVO.nullValue().getOidcDiscoveryUrl().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(OidcDiscoveryUrlVO.tryFrom(null).getOidcDiscoveryUrl().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        OidcDiscoveryUrlVO.from("one").getOidcDiscoveryUrl().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> OidcDiscoveryUrlVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", OidcDiscoveryUrlVO.from("one").toString());
  }
}
